!function(){"use strict";function reporteTpvCtrl($scope,mS,tS){$scope.configurations=[],$scope.empresas=[],$scope.initialLoad=()=>{try{$scope.configurations=[],$scope.empresas=[];let data={tipo:6,txtSearch:($scope.search,"")};mS.getData("get","/consumoTpv/Get?json="+JSON.stringify(data)).then(response=>{if("1"==response.code){let tempArray=JSON.parse(response.payload);$scope.configurations=tempArray[0],$scope.empresas=tempArray[1]}else tS.toastr("warning",response.message)},error=>{console.log(error)})}catch(error){console.log(error)}},$scope.initialLoad(),$scope.getReportApi=data=>{try{showLoader();let tempArray=JSON.parse(data)[0][0],parameters={rdlcProps:JSON.parse(tempArray.rdlcProps)[0],dataSources:JSON.parse(tempArray.dataSources)[0],rdlcParams:JSON.parse(tempArray.rdlcParams)[0]},urlReports=document.getElementById("urlReports").value;mS.getFile("POST",urlReports+"api/Reporte/GetReport",parameters).then(response=>{if(response){hideLoader();let fileBlob=new Blob([response.data],{type:response.headers()["content-type"]}),objectUrl,urlFile=(window.URL||window.webkitURL).createObjectURL(fileBlob);window.open(urlFile,"_blank")}},error=>{hideLoader(),console.log(error)})}catch(error){hideLoader(),console.log(error)}},$scope.getReport=()=>{try{let format,data={tipo:7,formato:1==2?"pdf":"excel",idConfigTpv:document.getElementById("idConfigTpv").value,idEmpresa:$scope.report.idEmpresa,fechaInicio:$scope.report.fechaInicio,fechaFin:$scope.report.fechaFin};mS.getData("get","/consumoTpv/Get?json="+JSON.stringify(data)).then(response=>{"1"==response.code&&$scope.getReportApi(response.payload)},error=>{console.log(error)})}catch(error){console.log(error)}}}app.controller("reporteTpvCtrl",reporteTpvCtrl),reporteTpvCtrl.$inject=["$scope","mainService","toastService"]}(window.angular);